package fx

import (
	"database/sql"
	"fmt"
	"os"
	"os/exec"
	"strings"
)

func compound(db *sql.DB) {
	q := "select "
	q += os.Getenv("Q")
	db.Exec(q)
}

func overwritten(db *sql.DB) {
	q := os.Getenv("Q")
	q = "safe"
	db.Exec(q)
}

func parameterized(db *sql.DB) { db.Exec("select ?", os.Getenv("Q")) }

func onlyDecides(db *sql.DB) {
	if os.Getenv("Q") == "" {
		db.Exec("a")
	}
}

func builder(db *sql.DB) {
	var b strings.Builder
	b.WriteString(os.Getenv("Q"))
	db.Exec(b.String())
}

func number(db *sql.DB) {
	n := len(os.Getenv("Q"))
	db.Exec(fmt.Sprintf("select %d", n))
}

func shell() { exec.Command("sh", "-c", os.Getenv("Q")).Run() }

func argv() { exec.Command("ls", os.Getenv("Q")).Run() }

func input() string { return os.Getenv("Q") }

func viaSource(db *sql.DB) { db.Exec(input()) }

func output(db *sql.DB, q string) { db.Exec(q) }

func viaSink(db *sql.DB) { output(db, os.Getenv("Q")) }

func ignoresIt(s string) string { return "constant" }

func viaIgnoring(db *sql.DB) { db.Exec(ignoresIt(os.Getenv("Q"))) }

type config struct{ a, b string }

func fields(db *sql.DB) {
	c := config{}
	c.a = os.Getenv("Q")
	db.Exec(c.b)
}
